namespace QuantForge.Core;public sealed record AndroidResearchHistoryEntry(string DraftFingerprint,string DatasetFingerprint,string StrategyFingerprint,AndroidResearchQueueState State,string Message);public static class AndroidResearchHistoryRules{public static IReadOnlyList<AndroidResearchHistoryEntry> Create(IEnumerable<AndroidResearchQueueItem> items){ArgumentNullException.ThrowIfNull(items);return items.Where(x=>x.State is AndroidResearchQueueState.Complete or AndroidResearchQueueState.Blocked or AndroidResearchQueueState.Invalid).Select(x=>new AndroidResearchHistoryEntry(x.DraftFingerprint,x.DatasetFingerprint,x.StrategyFingerprint,x.State,x.Message)).OrderBy(x=>x.DraftFingerprint,StringComparer.Ordinal).ToArray();}}
